const normalize = (value:string) => value.replace(/[()*‌\s]/g,'').replace(/تومان|درصد|دقیقه|انتخاب/g,'');
const parseNumber = (value:string) => Number(String(value||'').replace(/[۰-۹]/g,digit=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))).replace(/[٠-٩]/g,digit=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit))).replace(/[^\d.-]/g,'')) || 0;
const rowId = (row:Row) => row.__id;

function usePersistentState<T>(key:string,initial:T):[T,Dispatch<SetStateAction<T>>]{
  const [value,setValue]=useState<T>(initial);
  const [loaded,setLoaded]=useState(false);
  useEffect(()=>{
    let cancelled=false;
    const timer=window.setTimeout(()=>{
      if(cancelled)return;
      try{const saved=window.localStorage.getItem(key);if(saved)setValue(JSON.parse(saved) as T)}catch{}
      setLoaded(true);
    },0);
    return ()=>{cancelled=true;window.clearTimeout(timer)};
  },[key]);
  useEffect(()=>{if(!loaded)return;try{window.localStorage.setItem(key,JSON.stringify(value))}catch{}},[key,value,loaded]);
  return [value,setValue];
}

function columnForField(active:string, field:Field, columns:string[]){
  const mapped = fieldColumnMap[active]?.[field.name];
  if(mapped) return mapped;
  const exact = columns.find(column => normalize(column) === normalize(field.label));
  if(exact) return exact;
  return columns.find(column => normalize(column).includes(normalize(field.label)) || normalize(field.label).includes(normalize(column)));
}

function FieldControlV2({field,value}:{field:Field;value?:string}){
  if(field.type==='textarea') return <textarea name={field.name} placeholder={field.placeholder} required={field.required} defaultValue={value}/>;
  if(field.type==='select') return <select name={field.name} required={field.required} defaultValue={value||''}><option value="" disabled>انتخاب کنید</option>{field.options?.map(option=><option key={option}>{option}</option>)}</select>;
  if(field.type==='checkbox') return <label className="check-row"><input name={field.name} type="checkbox" defaultChecked={value ? /فعال|بله|true|on/.test(value) : true}/><span>{field.label}</span></label>;
  if(field.type==='radio') return <div className="radio-row">{field.options?.map((option,index)=><label key={option}><input name={field.name} type="radio" value={option} defaultChecked={value ? value===option : index===0}/>{option}</label>)}</div>;
  if(field.type==='file') return <input name={field.name} type="file"/>;
  return <input name={field.name} type={field.type||'text'} placeholder={field.placeholder} required={field.required} defaultValue={value}/>;
}

function ModalV2({title,onClose,children,footer,compact=false}:{title:string;onClose:()=>void;children:React.ReactNode;footer?:React.ReactNode;compact?:boolean}){
  return <div className="modal-backdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}>
    <section className={'modal-card '+(compact?'compact':'')} role="dialog" aria-modal="true" aria-label={title}>
      <header><h2>{title}</h2><button onClick={onClose} className="close-btn">⊗ بستن</button></header>
      <div className="modal-body">{children}</div>
      {footer&&<footer>{footer}</footer>}
    </section>
  </div>;
}

