function OperationalDashboard({notify,entries,expenses,stocks,bills,recipes,people,funds}:{notify:(message:string)=>void;entries:AccountingEntry[];expenses:ExpenseRecord[];stocks:StockItem[];bills:OpenBill[];recipes:Recipe[];people:AccountingPerson[];funds:string[]}){
  const today=new Date().toISOString().slice(0,10);
  const sales=entries.filter(entry=>entry.type==='RECEIPT'&&entry.channel==='فروش');
  const todaySales=sales.filter(entry=>entry.date===today).reduce((sum,entry)=>sum+entry.amount,0);
  const totalSales=sales.reduce((sum,entry)=>sum+entry.amount,0);
  const totalExpenses=expenses.reduce((sum,expense)=>sum+expense.amount,0);
  const operatingExpenses=expenses.filter(expense=>expense.category!=='خرید مواد اولیه').reduce((sum,expense)=>sum+expense.amount,0);
  const cogs=sales.reduce((sum,entry)=>sum+entry.cost,0);
  const totalCash=funds.reduce((sum,fund)=>sum+fundBalance(entries,fund),0);
  const inventoryValue=stocks.reduce((sum,stock)=>sum+stock.quantity*stock.avgCost,0);
  const openAmount=bills.filter(bill=>bill.status!=='تسویه‌شده').reduce((sum,bill)=>sum+bill.amount,0);
  const pending=entries.filter(entry=>entry.status==='در انتظار تسویه').reduce((sum,entry)=>sum+entry.amount,0);
  const profit=totalSales-operatingExpenses-cogs;
  const metrics=[['مانده کل صندوق‌ها',totalCash,'تومان'],['فروش امروز',todaySales,'تومان'],['صورت‌حساب باز',openAmount,'تومان'],['در انتظار تسویه',pending,'تومان'],['ارزش موجودی',inventoryValue,'تومان'],['سود عملیاتی',profit,'تومان'],['تعداد سفارش‌ها',sales.length,'سفارش'],['اشخاص ثبت‌شده',people.length,'شخص'],['رسپی فعال',recipes.filter(recipe=>recipe.active).length,'رسپی'],['مواد زیر نقطه سفارش',stocks.filter(stock=>stock.quantity<=stock.reorder).length,'قلم']];
  return <><div className="page-head"><div><p className="eyebrow">مرکز کنترل · محاسبه مستقیم از اسناد ثبت‌شده</p><h1>داشبورد</h1></div><button className="primary" onClick={()=>notify('همه شاخص‌ها از دفتر مالی و انبار دوباره محاسبه شدند.')}>به‌روزرسانی اطلاعات</button></div><section className="metric-grid">{metrics.map((metric,index)=><article className="metric-card" key={metric[0]}><div className={'metric-icon tone-'+index%3}>{['▰','↗','◎','▤','♙','★','◷','!','◒','×'][index]}</div><p>{metric[0]}</p><strong>{Number(metric[1]).toLocaleString('fa-IR')}</strong><small>{metric[2]}</small><span className="trend">براساس داده عملیاتی</span></article>)}</section><section className="dashboard-grid"><article className="panel"><div className="panel-head"><div><h2>تراز عملیاتی</h2><p>فروش، هزینه، مصرف رسپی و سود</p></div></div><div className="summary-grid"><article><span>فروش</span><b>{totalSales.toLocaleString('fa-IR')}</b></article><article><span>هزینه ثبت‌شده</span><b>{totalExpenses.toLocaleString('fa-IR')}</b></article><article><span>بهای مصرف رسپی</span><b>{Math.round(cogs).toLocaleString('fa-IR')}</b></article><article><span>سود</span><b className={profit<0?'negative':'positive'}>{Math.round(profit).toLocaleString('fa-IR')}</b></article></div></article><article className="panel"><div className="panel-head"><div><h2>مانده صندوق‌ها</h2><p>دریافت منهای پرداخت و انتقال</p></div></div><div className="fund-balance-list">{funds.map(fund=><div key={fund}><span>{fund}</span><b>{fundBalance(entries,fund).toLocaleString('fa-IR')} تومان</b></div>)}{!funds.length&&<div className="empty-state">صندوقی تعریف نشده است.</div>}</div></article></section><section className="panel data-panel"><div className="panel-head"><div><h2>آخرین اسناد مالی</h2><p>بدون داده نمونه</p></div></div><div className="table-scroll"><table><thead><tr><th>نوع</th><th>تاریخ</th><th>مرجع</th><th>بابت</th><th>شخص</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>{entries.slice(0,8).map(entry=><tr key={entry.id}><td>{entry.type==='RECEIPT'?'دریافت':entry.type==='PAYMENT'?'پرداخت':'انتقال'}</td><td>{entry.date}</td><td>{entry.reference}</td><td>{entry.subject}</td><td>{entry.person}</td><td>{entry.amount.toLocaleString('fa-IR')}</td><td>{entry.status}</td></tr>)}</tbody></table>{!entries.length&&<div className="empty-state">هنوز سند مالی ثبت نشده است.</div>}</div></section></>;
}

function KdsV2({notify,orders,setOrders}:{notify:(message:string)=>void;orders:KdsOrder[];setOrders:Dispatch<SetStateAction<KdsOrder[]>>}){
  const [tab,setTab]=useState('همه');
  const [showGuide,setShowGuide]=useState(true);
  const visible=tab==='همه'?orders:orders.filter(order=>order.status===tab);
  const transition=(id:string)=>setOrders(current=>current.map(order=>order.id===id?{...order,status:order.status==='جدید'?'در حال آماده‌سازی':'آماده تحویل'}:order));
  return <><div className="page-head"><div><p className="eyebrow">نمایشگر تولید</p><h1>KDS</h1></div><div className="head-actions"><button className="ghost" onClick={()=>{setOrders(current=>current.map(order=>({...order,status:'در حال آماده‌سازی'})));notify('همه سفارش‌ها در حال آماده‌سازی شدند.')}}>علامت‌گذاری همه سفارش‌ها به در حال آماده‌سازی</button><button className="mint-btn" onClick={()=>{setOrders(current=>current.map(order=>({...order,status:'آماده تحویل'})));notify('آماده‌سازی همه سفارش‌ها پایان یافت.')}}>علامت‌گذاری همه سفارش‌ها به پایان آماده‌سازی</button><button className="ghost" onClick={()=>{document.documentElement.requestFullscreen?.();notify('حالت تمام‌صفحه فعال شد.')}}>بزرگ‌نمایی صفحه</button></div></div>{showGuide&&<div className="kds-guide"><span>ⓘ</span><p>برای تغییر وضعیت هر سفارش از دکمه کارت استفاده کنید؛ عملیات گروهی همه سفارش‌های قابل مشاهده را تغییر می‌دهد.</p><button onClick={()=>setShowGuide(false)}>متوجه شدم</button></div>}<div className="kds-tabs">{['همه','جدید','در حال آماده‌سازی','آماده تحویل'].map(item=><button key={item} className={tab===item?'active':''} onClick={()=>setTab(item)}>{item==='همه'?'همه سفارش‌ها':item==='جدید'?'سفارش‌های جدید':item} ({item==='همه'?orders.length:orders.filter(order=>order.status===item).length})</button>)}</div><div className="kds-board">{visible.map((order,index)=><article className={'kds-ticket s'+index%3} key={order.id}><header><b>{order.id}</b><span>{order.time}</span></header><h3>{order.place}</h3><p>{order.items}</p><small className="status-line">{order.status}</small><footer>{order.status!=='آماده تحویل'?<button onClick={()=>{transition(order.id);notify('وضعیت سفارش '+order.id+' تغییر کرد.')}}>{order.status==='جدید'?'شروع آماده‌سازی':'آماده تحویل'}</button>:<button onClick={()=>{setOrders(current=>current.filter(item=>item.id!==order.id));notify('سفارش تحویل و از صف خارج شد.')}}>تحویل شد</button>}</footer></article>)}</div>{!visible.length&&<div className="empty-state">سفارشی در این وضعیت وجود ندارد.</div>}</>;
}

function BillsV2({notify,onCreate,onSettle,onDelete,products,funds,bills}:{notify:(message:string)=>void;onCreate:(bill:CreatedBill)=>boolean;onSettle:(bill:OpenBill,fund:string)=>boolean;onDelete:(bill:OpenBill)=>boolean;products:{product:string;price:number}[];funds:string[];bills:OpenBill[]}){
  const [query,setQuery]=useState('');
  const [place,setPlace]=useState('همه جایگاه‌ها');
  const [editing,setEditing]=useState<number|null>(null);
  const [creating,setCreating]=useState(false);
  const [billStep,setBillStep]=useState(1);
  const [settlementFund,setSettlementFund]=useState('');
  const [billMeta,setBillMeta]=useState({customerType:'حضوری',customer:'',place:'میز ۱',people:'1',address:''});
  const firstProduct=products[0]||{product:'',price:0};
  const [billItems,setBillItems]=useState<BillItem[]>(firstProduct.product?[{product:firstProduct.product,quantity:1,price:firstProduct.price}]:[]);
  const visible=bills.filter(bill=>(place==='همه جایگاه‌ها'||bill.place.includes(place))&&(!query||bill.place.includes(query)||String(bill.id).includes(query)));
  const submit=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!billItems.length||billItems.some(item=>!item.product||item.quantity<=0||item.price<0)){notify('حداقل یک محصول معتبر برای صورت‌حساب لازم است.');return}const data=new FormData(event.currentTarget);const table=billMeta.place||'میز جدید';const customer=billMeta.customer||'مشتری حضوری';const subtotal=billItems.reduce((sum,item)=>sum+item.price*item.quantity,0);const discountValue=Math.max(0,Number(data.get('discount')||0));const discountType=String(data.get('discountType')||'درصد');const discount=discountType==='درصد'?Math.round(subtotal*Math.min(100,discountValue)/100):Math.min(subtotal,discountValue);const serviceFee=Math.max(0,Number(data.get('serviceFee')||0));const tax=Math.max(0,Number(data.get('tax')||0));const deliveryFee=Math.max(0,Number(data.get('deliveryFee')||0));const amount=Math.max(0,subtotal-discount+serviceFee+tax+deliveryFee);const id=Math.max(0,...bills.map(bill=>bill.id))+1;const submitter=(event.nativeEvent as SubmitEvent).submitter as HTMLButtonElement|null;const paid=Boolean(submitter?.textContent?.includes('پرداخت'));const paymentFund=String(data.get('paymentFund')||'');if(paid&&!paymentFund){notify('برای پرداخت، صندوق دریافت را انتخاب کنید.');return}if(!onCreate({id,place:table,customer,items:billItems.map(item=>({...item})),subtotal,discount,serviceFee,tax,deliveryFee,amount,paid,paymentFund}))return;setCreating(Boolean(data.get('nextBill')));setBillStep(1);notify(paid?'صورت‌حساب ثبت، پرداخت و به مالی، انبار و KDS ارسال شد.':'صورت‌حساب باز ثبت و به انبار و KDS ارسال شد.')};
  return <><div className="page-head"><div><p className="eyebrow">فروش متصل به رسپی، انبار، KDS و حسابداری</p><h1>صورت‌حساب‌های باز</h1></div><button className="primary" disabled={!products.length} onClick={()=>{setCreating(true);setBillStep(1);setBillMeta({customerType:'حضوری',customer:'',place:'میز ۱',people:'1',address:''});setBillItems(firstProduct.product?[{product:firstProduct.product,quantity:1,price:firstProduct.price}]:[])}}>＋ صورت‌حساب جدید</button></div>{!products.length&&<div className="kds-guide"><span>ⓘ</span><p>ابتدا در بخش رسپی محصولات، حداقل یک محصول فعال با مواد اولیه تعریف کنید.</p></div>}<div className="bill-toolbar"><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="نام مشتری یا شماره فاکتور"/><select value={place} onChange={event=>setPlace(event.target.value)}><option>همه جایگاه‌ها</option><option>میز</option><option>بیرون‌بر</option></select><select><option>همه کاربران</option><option>صندوقدار</option><option>مدیر</option></select><select><option>همه وضعیت‌ها</option><option>باز</option><option>تسویه‌شده</option></select></div><div className="bill-grid">{visible.map(bill=><article className="bill-card" key={bill.id}><header><b>{bill.place}</b><span>{bill.status}</span></header><p>{persianDigits(bill.items.length)} آیتم · {persianDigits(bill.minutes)} دقیقه</p><strong>{bill.amount.toLocaleString('fa-IR')} تومان</strong><footer><button onClick={()=>setEditing(bill.id)}>مشاهده و ویرایش</button></footer></article>)}</div>{!visible.length&&<div className="empty-state">صورت‌حسابی ثبت نشده است.</div>}
    {creating&&<ModalV2 title={'ایجاد صورت‌حساب · مرحله '+persianDigits(billStep)} onClose={()=>setCreating(false)} footer={billStep===1?<button className="primary" onClick={()=>setBillStep(2)}>مرحله بعد: محصول</button>:<><button className="ghost" onClick={()=>setBillStep(1)}>مرحله قبل</button><button form="bill-create" className="ghost" type="submit">ثبت سفارش</button><button form="bill-create" className="primary" type="submit">ثبت و پرداخت</button></>}><form id="bill-create" className="form-grid" onSubmit={submit}>{billStep===1?<><div className="form-field"><label>نوع مشتری*</label><select name="customerType" value={billMeta.customerType} onChange={event=>setBillMeta(current=>({...current,customerType:event.target.value}))}><option>حضوری</option><option>دریافت حضوری</option><option>ارسال به آدرس مشتری</option></select></div><div className="form-field"><label>نام مشتری، شماره اشتراک، شماره موبایل</label><input name="customer" value={billMeta.customer} onChange={event=>setBillMeta(current=>({...current,customer:event.target.value}))} placeholder="جستجوی مشتری"/></div><div className="form-field"><label>جایگاه‌ها*</label><select name="place" value={billMeta.place} onChange={event=>setBillMeta(current=>({...current,place:event.target.value}))} required><option>میز ۱</option><option>میز ۲</option><option>بیرون‌بر</option></select></div><div className="form-field"><label>تعداد مشتریان</label><input name="people" type="number" min="1" value={billMeta.people} onChange={event=>setBillMeta(current=>({...current,people:event.target.value}))}/></div><div className="form-field wide"><label>آدرس مشتری</label><textarea name="address" value={billMeta.address} onChange={event=>setBillMeta(current=>({...current,address:event.target.value}))}/></div></>:<><div className="bill-items wide">{billItems.map((item,index)=><div className="bill-item-row" key={index}><select value={item.product} onChange={event=>{const selected=products.find(product=>product.product===event.target.value);setBillItems(current=>current.map((line,lineIndex)=>lineIndex===index?{...line,product:event.target.value,price:selected?.price||line.price}:line))}}>{products.map(product=><option key={product.product}>{product.product}</option>)}</select><input aria-label="تعداد" type="number" min="1" value={item.quantity} onChange={event=>setBillItems(current=>current.map((line,lineIndex)=>lineIndex===index?{...line,quantity:Number(event.target.value)}:line))}/><input aria-label="قیمت" type="number" min="0" value={item.price} onChange={event=>setBillItems(current=>current.map((line,lineIndex)=>lineIndex===index?{...line,price:Number(event.target.value)}:line))}/><button type="button" className="danger-text" onClick={()=>setBillItems(current=>current.filter((_,lineIndex)=>lineIndex!==index))}>حذف محصول</button></div>)}<button type="button" className="ghost" onClick={()=>setBillItems(current=>[...current,{product:firstProduct.product,quantity:1,price:firstProduct.price}])}>＋ افزودن محصول</button></div><div className="form-field"><label>تخفیف کلی</label><input name="discount" type="number" min="0"/></div><div className="form-field"><label>نوع تخفیف</label><select name="discountType"><option>درصد</option><option>مبلغ</option></select></div><div className="form-field"><label>حق سرویس (تومان)</label><input name="serviceFee" type="number" min="0"/></div><div className="form-field"><label>مالیات (تومان)</label><input name="tax" type="number" min="0"/></div><div className="form-field"><label>هزینه ارسال (تومان)</label><input name="deliveryFee" type="number" min="0"/></div><div className="form-field"><label>صندوق دریافت</label><select name="paymentFund" defaultValue=""><option value="">هنگام ثبت سفارش انتخاب نمی‌شود</option>{funds.map(fund=><option key={fund}>{fund}</option>)}</select></div><label className="check-row"><input name="nextBill" type="checkbox"/><span>ساخت صورت‌حساب بعدی</span></label><label className="check-row"><input name="printProduction" type="checkbox"/><span>چاپ صورت‌حساب تولید</span></label><div className="form-field wide"><label>توضیحات صورت‌حساب</label><textarea name="description"/></div></>}</form></ModalV2>}
    {editing!==null&&bills.find(bill=>bill.id===editing)&&<ModalV2 title="جزئیات صورت‌حساب" onClose={()=>setEditing(null)} footer={<><button className="danger-soft" onClick={()=>{const bill=bills.find(item=>item.id===editing);if(bill&&onDelete(bill))setEditing(null)}}>حذف</button>{bills.find(item=>item.id===editing)?.status!=='تسویه‌شده'&&<button className="primary" onClick={()=>{const bill=bills.find(item=>item.id===editing);if(bill&&onSettle(bill,settlementFund))setEditing(null)}} disabled={!settlementFund}>تسویه کامل</button>}</>}><div className="details-grid">{Object.entries(bills.find(bill=>bill.id===editing)||{}).filter(([key])=>key!=='items').map(([key,value])=><div key={key}><span>{key}</span><b>{String(value)}</b></div>)}</div>{bills.find(item=>item.id===editing)?.status!=='تسویه‌شده'&&<div className="form-field"><label>صندوق تسویه*</label><select value={settlementFund} onChange={event=>setSettlementFund(event.target.value)}><option value="">انتخاب کنید</option>{funds.map(fund=><option key={fund}>{fund}</option>)}</select></div>}</ModalV2>}
  </>;
}

