    const created=lines.map((line,index)=>{const stock=stocks.find(item=>item.id===line.materialId);const transactionType=kind==='OUT'&&destination!==source?'TRANSFER':kind;const unitPrice=line.unitPrice||stock?.avgCost||0;return {id:'txn-'+String(Date.now())+'-'+String(index),type:transactionType,date:meta.date||new Date().toISOString().slice(0,10),material:stock?.material||'ماده اولیه',unit:stock?.unit||'واحد',quantity:line.quantity,from:kind==='IN'?'خرید':source,to:destination,unitPrice,total:unitPrice*line.quantity,reference:meta.reference||'DOC-'+String(Date.now()),status:'ثبت‌شده'} as InventoryTransaction});
