    setStocks(current=>{const next=current.map(item=>({...item}));for(const line of lines){const index=next.findIndex(item=>item.id===line.materialId);if(index<0)continue;const currentStock=next[index];if(kind==='IN'){const newQuantity=currentStock.quantity+line.quantity;const newCost=newQuantity?Math.round((currentStock.quantity*currentStock.avgCost+line.quantity*(line.unitPrice||currentStock.avgCost))/newQuantity):currentStock.avgCost;next[index]={...currentStock,quantity:newQuantity,avgCost:newCost,warehouse:destination}}else{next[index]={...currentStock,quantity:Math.max(0,currentStock.quantity-line.quantity)};if(destination!==source){const destinationIndex=next.findIndex(item=>item.material===currentStock.material&&item.warehouse===destination);if(destinationIndex>=0)next[destinationIndex]={...next[destinationIndex],quantity:next[destinationIndex].quantity+line.quantity};else next.push({...currentStock,id:currentStock.id+'-dest-'+String(next.length+1),warehouse:destination,quantity:line.quantity})}}}return next});
